begin;
insert into public.admin_permissions(permission_key,name_ar,category) values
 ('website.read','قراءة إدارة الموقع','website'),('website.manage','تعديل مسودة الموقع والوسائط','website'),('website.publish','نشر محتوى الموقع','website') on conflict(permission_key) do nothing;
insert into public.admin_role_permissions(role_id,permission_key) select r.id,p.permission_key from public.admin_roles r cross join public.admin_permissions p where r.role_key='super_admin' and p.category='website' on conflict do nothing;
create table public.zameel_website_state(id integer primary key check(id=1),revision bigint not null default 0,draft jsonb not null,published jsonb not null,updated_at timestamptz not null default now(),published_at timestamptz not null default now());
create table public.zameel_website_versions(id bigint generated always as identity primary key,content jsonb not null,actor_id uuid references public.users(id) on delete set null,note text not null default '',created_at timestamptz not null default now());
create table public.zameel_website_assets(path text primary key,actor_id uuid references public.users(id) on delete set null,mime text not null,size bigint not null,created_at timestamptz not null default now());
alter table public.zameel_website_state enable row level security;
alter table public.zameel_website_versions enable row level security;
alter table public.zameel_website_assets enable row level security;
revoke all on public.zameel_website_state,public.zameel_website_versions,public.zameel_website_assets from public,anon,authenticated;
grant all on public.zameel_website_state,public.zameel_website_versions,public.zameel_website_assets to service_role;
grant usage,select on sequence public.zameel_website_versions_id_seq to service_role;
insert into public.zameel_website_state(id,draft,published) values(1,$seed${"schema": 1, "pages": [{"id": "/", "title": "الرئيسية", "blocks": [{"id": "base-0", "kind": "existing", "label": "الشريط العلوي", "fields": {"f0": "/", "f1": "/assets/zameel-logo.png", "f2": "شعار زميل", "f3": "ZAMEEL ", "f4": "زميل", "f5": "#about", "f6": "عن زميل", "f7": "#app-tour", "f8": "داخل التطبيق", "f9": "/privacy/", "f10": "الخصوصية", "f11": "/support/", "f12": "الدعم", "f13": "/delete-account/", "f14": "حذف الحساب"}, "hidden": []}, {"id": "base-1", "kind": "existing", "label": "زميل. مجتمعك أقرب.", "fields": {"f0": " من الأردن، إلى كل من يبحث عن زميل", "f1": "زميل.", "f2": "مجتمعك أقرب.", "f3": "منصة أردنية تجمع التواصل والمعرفة والفرص في تجربة واحدة، مفتوحة للجميع، وبخدمات تنتمي إلى الحياة الجامعية.", "f4": "شارك المنشورات والحالات والشورتس، وابنِ زمالات جديدة عبر الدردشة والمكالمات الصوتية والمرئية. اكتشف المكتبة وتبادل الكتب، واجتمع للدراسة أو تقديم المحاضرات، واستفد من زميل AI وفرص العمل والتدريب وخدمات المجتمع.", "f5": "#app-tour", "f6": "شاهد زميل من الداخل ↓", "f7": "/support/", "f8": "تواصل معنا", "f9": "قريبًا على المتاجر · ستُضاف روابط التنزيل الرسمية عند الإطلاق", "f10": "/assets/campus.webp", "f11": "مشهد توضيحي لزملاء في حرم جامعي أردني", "f12": "لحظات تجمعنا ", "f13": "/assets/zameel-logo.png", "f14": "", "f15": " زميلك أقرب مما تتخيّل"}, "hidden": []}, {"id": "base-2", "kind": "existing", "label": "كل ما تحتاجه لتتواصل، تتعلّم، وتكتشف.", "fields": {"f0": "تجربة واحدة، وأبواب كثيرة", "f1": "كل ما تحتاجه لتتواصل،", "f2": "تتعلّم، وتكتشف.", "f3": "01", "f4": "التواصل والمحتوى", "f5": "منشورات نصية وصور وفيديوهات، حالات وشورتس، وإعجابات وتعليقات ومشاركات، مع خيارات لتحديد جمهور المحتوى، وتنزيل الصور والشورتس المتاحة للحفظ بعلامة زميل.", "f6": "02", "f7": "الدردشة والمكالمات", "f8": "رسائل وصور وفيديوهات ومقاطع صوتية، مكالمات صوتية ومرئية، وإشعارات تساعدك على متابعة الرسائل والتفاعل.", "f9": "03", "f10": "المكتبة وتبادل الكتب", "f11": "ملفات ومراجع دراسية، وبيع الكتب وتبادلها وإعارتها والتبرع بها، مع الحجز والتواصل مع صاحب الكتاب ومتابعة الطلب.", "f12": "04", "f13": "اجتمع بزميل", "f14": "مساحة للاجتماعات متعددة المشاركين، والتعاون في الدراسة وتقديم المحاضرات والجلسات التعليمية بالصوت والفيديو.", "f15": "05", "f16": "زميل AI", "f17": "مساعد داخل التطبيق يساندك في الأسئلة وشرح الأفكار والتعلم وتنظيم المعرفة.", "f18": "06", "f19": "الوظائف وفرص التدريب", "f20": "مسار لاكتشاف الوظائف والفرص التدريبية، يساعد الطلبة وغيرهم على الانتقال من المعرفة إلى التجربة العملية.", "f21": "07", "f22": "المجتمع الجامعي", "f23": "مساحات للجامعة والكلية والتخصص والدفعة، وتقويم أكاديمي، وخدمات للمجتمع الجامعي وشركاء زميل.", "f24": "08", "f25": "العالم القريب منك", "f26": "اكتشاف الحرم الجامعي والمحيط القريب، مع زمالات مقترحة تساعد على بناء مجتمع أكثر ترابطًا.", "f27": "09", "f28": "الراديو والاستطلاعات", "f29": "راديو زميل للمشاركة الصوتية، واستطلاعات للرأي، وتحدي أجمل كلية للاحتفاء بصور الحياة الجامعية.", "f30": "10", "f31": "التعلم والألعاب", "f32": "كويز للأسئلة والمعرفة، وثقة أم غدر للتعاون واتخاذ القرار، بعملات افتراضية داخل تجربة اللعب.", "f33": "11", "f34": "حسابك ومظهرك", "f35": "تسجيل بالبريد الإلكتروني مع تأكيده، وملف شخصي وإعدادات مستقلة للحساب والتطبيق، ومظهر فاتح وداكن وأصلي، وخدمة توثيق مدفوعة بعد مراجعة الإدارة.", "f36": "12", "f37": "الترويج والخصوصية", "f38": "ترويج المنشورات العامة باختيار المدة والجمهور والمناطق أو الجامعات والعمر والجنس، إلى جانب التحكم بالخصوصية والإبلاغ والحذف والدعم."}, "hidden": []}, {"id": "base-3", "kind": "existing", "label": "تعرف على تجربتك القادمة.", "fields": {"f0": "من داخل زميل", "f1": "تعرف على تجربتك القادمة.", "f2": "صور من واجهات التطبيق؛ افتح أي صورة لاستكشافها بالحجم الكامل.", "f3": "كل الواجهات", "f4": "التواصل والمشاركة", "f5": "المعرفة والتعلم", "f6": "المجتمع والخدمات", "f7": "/assets/app-screen-02.webp", "f8": "أخبار زملائك، في مكان واحد — واجهة زميل", "f9": "عرض الصورة ↗", "f10": "أخبار زملائك، في مكان واحد", "f11": "شارك النصوص والصور والفيديوهات، وتابع ما يهمك في المجتمع العام أو الجامعة وا