ng", "label": "أسرة زميل", "fields": {"f0": "أسرة زميل", "f1": "/assets/zameel-family-mohammad.webp", "f2": "محمد مشهور — أسرة زميل", "f3": "محمد مشهور"}, "hidden": []}, {"id": "base-9", "kind": "existing", "label": "الجامعة تجمعكم. زميل يقرّبكم.", "fields": {"f0": "/assets/zameel-logo.png", "f1": "شعار زميل", "f2": "الجامعة تجمعكم.", "f3": "زميل يقرّبكم.", "f4": "تابع استعدادات الإطلاق، أو تواصل معنا للاستفسار.", "f5": "/support/", "f6": "تواصل مع زميل ←"}, "hidden": []}, {"id": "base-10", "kind": "existing", "label": "أسفل الصفحة", "fields": {"f0": "© 2026 Zameel — زميل · ", "f1": "mailto:zameel.jo@gmail.com", "f2": "تواصل مع إدارة زميل", "f3": "https://mail.google.com/mail/?view=cm&fs=1&to=zameel.jo%40gmail.com", "f4": "فتح Gmail", "f5": "نسخ البريد", "f6": " · ", "f7": "/privacy/", "f8": "سياسة الخصوصية", "f9": " · ", "f10": "/child-safety/", "f11": "حماية الأطفال"}, "hidden": []}]}, {"id": "/privacy/", "title": "الخصوصية", "blocks": [{"id": "base-0", "kind": "existing", "label": "الشريط العلوي", "fields": {"f0": "/", "f1": "/assets/zameel-logo.png", "f2": "شعار زميل", "f3": "ZAMEEL ", "f4": "زميل", "f5": "/privacy/", "f6": "الخصوصية", "f7": "/support/", "f8": "الدعم", "f9": "/delete-account/", "f10": "حذف الحساب"}, "hidden": []}, {"id": "base-1", "kind": "existing", "label": "قسم 1", "fields": {"f0": "سياسة خصوصية زميل — Zameel"}, "hidden": []}, {"id": "base-2", "kind": "existing", "label": "قسم 2", "fields": {"f0": "آخر تحديث: ", "f1": "7 أكتوبر 2026", "f2": "التواصل مع إدارة زميل بشأن الخصوصية: ", "f3": "mailto:zameel.jo@gmail.com", "f4": "zameel.jo@gmail.com", "f5": "https://mail.google.com/mail/?view=cm&fs=1&to=zameel.jo%40gmail.com", "f6": "فتح Gmail", "f7": "نسخ البريد"}, "hidden": []}, {"id": "base-3", "kind": "existing", "label": "قسم 3", "fields": {"f0": "توضح هذه السياسة كيفية معالجة تطبيق زميل وخدماته المرتبطة بياناتك عند التسجيل والتواصل ونشر المحتوى واستخدام الخدمات الجامعية والإعلانات. يمكنك التواصل مع إدارة زميل عبر البريد أعلاه للاستفسار عن معالجة بياناتك أو طلب تصحيحها أو حذفها."}, "hidden": []}, {"id": "base-4", "kind": "existing", "label": "قسم 4", "fields": {"f0": "1. البيانات التي نعالجها"}, "hidden": []}, {"id": "base-5", "kind": "existing", "label": "قسم 5", "fields": {"f0": "بيانات الحساب والملف الشخصي (رقم الهاتف إلزامي، ويجري التحقق من البريد فقط): الاسم، البريد الإلكتروني، رقم الهاتف، صورة الملف، الجامعة والكلية والتخصص والسنة الدراسية والجنس، والبيانات الإضافية التي تدخلها في الميزات التي تستخدمها.", "f1": "محتوى وتفاعلات: المنشورات والصور والفيديوهات والحالات والكليبسات والرسائل والملفات والتعليقات والإعجابات والمشاهدات وطلبات الزمالة، وبيانات استخدام الخدمات مثل الكتب والمجموعات والاجتماعات.", "f2": "بيانات الميزات الاختيارية: الموقع عند منح الإذن، وأرقام جهات الاتصال المقروءة على الجهاز عند منح إذن الوصول. تُحوّل الأرقام في ميزة اقتراح الزملاء إلى بصمات رقمية وترسل للمطابقة؛ هذه البصمات ليست ضمانًا لإخفاء الهوية بالكامل.", "f3": "الصوت والصورة والملفات التي تختار مشاركتها، واستخدام الكاميرا والميكروفون عند تشغيل الميزات ذات الصلة مثل المكالمات أو التسجيل أو النشر.", "f4": "بيانات تشغيلية: معرّفات الحساب والجلسات، رموز توصيل الإشعارات، وبيانات الطلبات والأخطاء والاتصال التي تعالجها البنية التقنية لتشغيل الخدمة وتأمينها.", "f5": "للشركاء وفريق المبيعات: بيانات حساب العمل، الفريق والدور، بيانات الشريك والإعلان وموقعه ووسائطه، وقرارات المراجعة ونتائج التفاعل."}, "hidden": []}, {"id": "base-6", "kind": "existing", "label": "قسم 6", "fields": {"f0": "2. أسباب استخدام البيانات"}, "hidden": []}, {"id": "base-7", "kind": "existing", "label": "قسم 7", "fields": {"f0": "نستخدم البيانات لتشغيل الحساب والتحقق منه، وعرض المحتوى وفق إعدادات الجمهور، والتواصل والخدمات الجامعية، واقتراح الزملاء، وعرض المواقع والخدمات ذات الصلة، وإيصال الإشعارات، وتشغيل الإعلانات ومراجعتها وقياس التفاعل معها. كما تستخدم البيانات لمعالجة البلاغات والدعم وحماية الخدمة وتشخيص الأعطال وتحسين الأداء."}, "hidden": []}, {"id": "base-8", "kind": "existing", "label": "قسم 8", "fields": {"f0": "3. من يستطيع رؤية البيانات؟"}, "hidden": []}, {"id": "base-9", "kind": "existing", "label": "قسم 9", "fields": {"f0": "يرى المستخدمون معلومات الملف والمحتوى والتفاعلات وفق إعدادات الخصوصية والجمهور المتاحة في الميزة. تصل الرسائل والمحتويات التي ترسلها إلى المستلمين المعنيين. قد تظهر التعليقات والإعجابات وهوية صاحبها للجمهور الذي يستطيع الوصول إلى المحتوى؛ لا تفترض أن كل التفاعلات مجهولة."}, "hidden": []}, {"id": "base-10", "kind": "existing", "label": "قسم 10", "fields": {"f0": "يرى المعلن إعلاناته وإحصاءات المشاهدات والإعجابات والتعليقات المتاحة له، ويمكنه الرد على التعليقات. تصل إلى الموظفين المخوّلين بيانات العمل اللازمة لمهامهم وفق الصلاحيات، مثل مراجعة الإعلانات والبلاغات والدعم. قد يحتفظ الآخرون بنسخ من محتوى سبق أن شاركته معهم خارج زميل؛ لا يستطيع التطبيق حذف نسخهم الخارجية."}, "hidden": []}, {"id": "base-11", "kind": "existing", "label": "قسم 11", "fields": {"f0": "4. مزودو الخدمات والمعالجة خارج بلدك"}, "hidden": []}, {"id": "base-12", "kind": "existing", "label": "قسم 12", "fields": {"f0": "يعتمد زميل على Supabase للمصادقة وقاعدة البيانات والتخزين والوظائف الخلفية، وFirebase/Google لتوصيل الإشعارات، وخدمات استضافة الويب، ومنها Vercel للواجهة القائمة وCloudflare لاستضافة صفحات هذا الموقع. تستخدم المكالمات والاجتماعات بنية الاتصال وخدمات التوجيه أو الاجتماعات المهيأة للميزة، بما فيها LiveKit عند تشغيل الاجتماعات. يتلقى مزود الخدمة البيانات اللازمة لأداء خدمته، وقد تعالج على خوادم خارج الأردن بحسب إعدادات الاستضافة ومواقع مزودي الخدمة."}, "hidden": []}, {"id": "base-13", "kind": "existing", "label": "قسم 13", "fields": {"f0": "عند استخدام مساعد زميل الذكي، قد يرسل سؤالك وسياق المحادثة الحديث وبيانات الجامعة والكلية والتخصص ذات الصلة إلى Google Gemini لإنتاج الإجابة. تجنّب إدخال كلمات المرور أو البيانات المالية أو الصحية أو معلومات الآخرين الحساسة. معالجة المزود للبيانات تخضع لشروط خدمته؛ لا نعد بأن حذف المحادثة داخل زميل يمحو فورًا أي سجلات لدى المزود."}, "hidden": []}, {"id": "base-14", "kind": "existing", "label": "قسم 14", "fields": {"f0": "قد يلزم الإفصاح عن بيانات محددة استجابة لطلب قانوني ملزم. عند فتح رابط خارجي، تنطبق أيضًا سياسة الموقع الذي تزوره."}, "hidden": []}, {"id": "base-15", "kind": "existing", "label": "قسم 15", "fields": {"f0": "5. الأذونات والتحكم"}, "hidden": []}, {"id": "base-16", "kind": "existing", "label": "قسم 16", "fields": {"f0": "يمكنك إدارة أذونات الموقع وجهات الاتصال والكاميرا والميكروفون والإشعارات من إعدادات الجهاز. قد يؤدي رفض إذن أو سحبه إلى تعطيل الوظيفة التي تعتمد عليه. سحب الإذن يمنع الوصول اللاحق وفق نظام الجهاز، ولا يعني تلقائيًا حذف بيانات سبق إرسالها. يمكنك تعديل بيانات حسابك وإعدادات الخصوصية المتاحة أو طلب المساعدة عبر بريد الخصوصية."}, "hidden": []}, {"id": "base-17", "kind": "existing", "label": "قسم 17", "fields": {"f0": "6. التخزين المؤقت على الجهاز"}, "hidden": []}, {"id": "base-18", "kind": "existing", "label": "قسم 18", "fields": {"f0": "يحتفظ التطبيق بنسخ محلية مؤقتة من المحتوى لتسريع العرض وتقليل التنزيل المتكرر، وينظفها وفق آليات التطبيق وإعدادات الجهاز. قد تبقى ملفات حفظتها عمدًا في الاستديو أو خارج التطبيق بعد تسجيل الخروج أو حذف الحساب."}, "hidden": []}, {"id": "base-19", "kind": "existing", "label": "قسم 19", "fields": {"f0": "7. الاحتفاظ بالبيانات وحذف الحساب"}, "hidden": []}, {"id": "base-20", "kind": "existing", "label": "قسم 20", "fields": {"f0": "تبقى بيانات الحساب والمحتوى في الخدمة ما دامت لازمة لتشغيل الحساب والميزات، إلى أن تحذفها أو يُعالج طلب حذف الحساب، مع مراعاة طبيعة المحتوى المشترك والالتزامات الملزمة. يمكنك بدء الطلب من إعدادات الحساب داخل التطبيق أو من ", "f1": "/delete-account/", "f2": "صفحة طلب حذف الحساب", "f3": " دون الحاجة إلى التطبيق. يمكن إرسال الطلب من بريد الحساب المسجّل أو عبر الدعم، ثم التحقق من ملكية الحساب قبل الحذف؛ لا تتطلب قراءة الصفحة تسجيل الدخول."}, "hidden": []}, {"id": "base-21", "kind": "existing", "label": "قسم 21", "fields": {"f0": "يُعالج الحذف في الخلفية. قبول الطلب أو تسجيل الخروج لا يعني اكتمال الحذف. تنفذ الآلية إزالة بيانات الحساب ومحتواه الشخصي الذي تغطيه عملية التنظيف وملفاته المرتبطة، ثم حساب الدخول، وتعيد محاولة المراحل المتعثرة. قد يستغرق ذلك عدة دقائق أو أطول عند حدوث عطل. تحفظ معرّفات مهمة الحذف المكتملة لمدة سبعة أيام ثم تنظف دوريًا."}, "hidden": []}, {"id": "base-22", "kind": "existing", "label": "قسم 22", "fields": {"f0": "إذا كان الحساب مرتبطًا بإدارة أو مبيعات أو شريك تجاري، أو يملك مجموعة أو لَمّة أو دفتر تخرج أو اجتماعًا، فقد يتوقف الطلب الآلي ليتطلب مراجعة الصلاحيات أو نقل ملكية المحتوى المشترك. تواصل عبر ", "f1": "mailto:zameel.jo@gmail.com", "f2": "بريد الخصوصية", "f3": "https://mail.google.com/mail/?view=cm&fs=1&to=zameel.jo%40gmail.com", "f4": "فتح Gmail", "f5": "نسخ البريد", "f6": " لبدء معالجة هذه الحالة. هذه الحالات ليست مشمولة حاليًا بالحذف الآلي المباشر؛ المراجعة تحمي بيانات الآخرين ولا تعني أن الحساب حُذف."}, "hidden": []}, {"id": "base-23", "kind": "existing", "label": "قسم 23", "fields": {"f0": "قد تبقى البيانات المحذوفة في النسخ الاحتياطية حتى انتهاء دورة الاحتفاظ المطبقة لدى مزود الخدمة، ولا تستخدم هذه النسخ لإعادة تفعيل الحساب. تخضع السجلات التشغيلية والنسخ الاحتياطية لإعدادات المشروع وسياسات المزود. يمكن طلب معلومات مدة الاحتفاظ المطبقة عبر بريد الخصوصية؛ لا نعلن مدة موحّدة غير متحقق منها لكل أنواع السجلات. قد تبقى سجلات إدارية لازمة للمراجعة دون ربطها بحساب المستخدم بعد إزالة المرجع."}, "hidden": []}, {"id": "base-24", "kind": "existing", "label": "قسم 24", "fields": {"f0": "8. حماية البيانات"}, "hidden": []}, {"id": "base-25", "kind": "existing", "label": "قسم 25", "fields": {"f0": "تستخدم الخدمة وسائل المصادقة وصلاحيات الوصول والاتصالات الآمنة في المكونات المهيأة لذلك. لا توجد خدمة تمنح ضمانًا مطلقًا ضد كل المخاطر. حافظ على سرية بيانات دخولك، وأبلغ بريد الخصوصية إذا اشتبهت في وصول غير مصرح به إلى حسابك."}, "hidden": []}, {"id": "base-26", "kind": "existing", "label": "قسم 26", "fields": {"f0": "9. طلبات الخصوصية والتحديثات"}, "hidden": []}, {"id": "base-27", "kind": "existing", "label": "قسم 27", "fields": {"f0": "للاستفسار أو طلب الوصول إلى بياناتك أو تصحيحها أو حذفها، اكتب إلى ", "f1": "mailto:zameel.jo@gmail.com", "f2": "zameel.jo@gmail.com", "f3": "https://mail.google.com/mail/?view=cm&fs=1&to=zameel.jo%40gmail.com", "f4": "فتح Gmail", "f5": "نسخ البريد", "f6": " مع بريد الحساب ووصف الطلب، دون إرسال كلمة المرور. قد نحتاج إلى التحقق من ملكية الحساب. إذا تغيّرت الممارسات، نحدّث هذه الصفحة وتاريخها ونقدم الإفصاحات والموافقات اللازمة داخل التطبيق للمعالجة التي تتطلبها."}, "hidden": []}, {"id": "base-28", "kind": "existing", "label": "أسفل الصفحة", "fields": {"f0": "© 2026 Zameel — زميل · ", "f1": "mailto:zameel.jo@gmail.com", "f2": "تواصل مع إدارة زميل", "f3": "https://mail.google.com/mail/?view=cm&fs=1&to=zameel.jo%40gmail.com", "f4": "فتح Gmail", "f5": "نسخ البريد", "f6": " · ", "f7": "/privacy/", "f8": "سياسة الخصوصية", "f9": " · ", "f10": "/child-safety/", "f11": "حماية الأطفال"}, "hidden": []}]}, {"id": "/support/", "title": "الدعم", "blocks": [{"id": "base-0", "kind": "existing", "label": "الشريط العلوي", "fields": {"f0": "/", "f1": "/assets/zameel-logo.png", "f2": "شعار زميل", "f3": "ZAMEEL ", "f4": "زميل", "f5": "/privacy/", "f6": "الخصوصية", "f7": "/support/", "f8": "الدعم", "f9": "/delete-account/", "f10": "حذف الحساب"}, "hidden": []}, {"id": "base-1", "kind": "existing", "label": "قسم 1", "fields": {"f0": "مساعدة زميل"}, "hidden": []}, {"id": "base-2", "kind": "existing", "label": "قسم 2", "fields": {"f0": "كيف نساعدك؟"}, "hidden": []}, {"id": "base-3", "kind": "existing", "label": "قسم 3", "fields": {"f0": "أرسل وصف المشكلة، إصدار التطبيق ونوع هاتفك. يمكنك إرفاق لقطة للشاشة بعد إخفاء البيانات الحساسة."}, "hidden": []}, {"id": "base-4", "kind": "existing", "label": "قسم 4", "fields": {"f0": "https://wa.me/962792009821", "f1": "تواصل عبر واتساب"}, "hidden": []}, {"id": "base-5", "kind": "existing", "label": "قسم 5", "fields": {}, "hidden": []}, {"id": "base-6", "kind": "existing", "label": "قسم 6", "fields": {"f0": "mailto:zameel.jo@gmail.com?subject=Zameel%20Support", "f1": "تواصل عبر البريد"}, "hidden": []}, {"id": "base-7", "kind": "existing", "label": "قسم 7", "fields": {"f0": "https://mail.google.com/mail/?view=cm&fs=1&to=zameel.jo%40gmail.com&su=Zameel%20Support", "f1": "فتح Gmail", "f2": "نسخ البريد"}, "hidden": []}, {"id": "base-8", "kind": "existing", "label": "قسم 8", "fields": {"f0": "zameel.jo@gmail.com"}, "hidden": []}, {"id": "base-9", "kind": "existing", "label": "قسم 9", "fields": {"f0": "لا ترسل كلمة المرور أو رمز التحقق أو بيانات البطاقة. الدعم لا يحتاج هذه المعلومات."}, "hidden": []}, {"id": "base-10", "kind": "existing", "label": "قسم 10", "fields": {"f0": "استعادة كلمة المرور"}, "hidden": []}, {"id": "base-11", "kind": "existing", "label": "قسم 11", "fields": {"f0": "من شاشة الدخول اختر «نسيت كلمة المرور»، وأدخل بريدك المسجّل ثم اتبع خطوات التحقق."}, "hidden": []}, {"id": "base-12", "kind": "existing", "label": "قسم 12", "fields": {"f0": "حذف الحساب والبيانات"}, "hidden": []}, {"id": "base-13", "kind": "existing", "label": "قسم 13", "fields": {"f0": "يمكن بدء طلبك من ", "f1": "/delete-account/", "f2": "صفحة حذف الحساب", "f3": " أو إعدادات الحساب داخل التطبيق."}, "hidden": []}, {"id": "base-14", "kind": "existing", "label": "أسفل الصفحة", "fields": {"f0": "© 2026 Zameel — زميل · ", "f1": "mailto:zameel.jo@gmail.com", "f2": "تواصل مع إدارة زميل", "f3": "https://mail.google.com/mail/?view=cm&fs=1&to=zameel.jo%40gmail.com", "f4": "فتح Gmail", "f5": "نسخ البريد", "f6": " · ", "f7": "/privacy/", "f8": "سياسة الخصوصية", "f9": " · ", "f10": "/child-safety/", "f11": "حماية الأطفال"}, "hidden": []}]}, {"id": "/delete-account/", "title": "حذف الحساب", "blocks": [{"id": "base-0", "kind": "existing", "label": "الشريط العلوي", "fields": {"f0": "/", "f1": "/assets/zameel-logo.png", "f2": "شعار زميل", "f3": "ZAMEEL ", "f4": "زميل", "f5": "/privacy/", "f6": "الخصوصية", "f7": "/support/", "f8": "الدعم", "f9": "/delete-account/", "f10": "حذف الحساب"}, "hidden": []}, {"id": "base-1", "kind": "existing", "label": "قسم 1", "fields": {"f0": "حسابك، قرارك"}, "hidden": []}, {"id": "base-2", "kind": "existing", "label": "قسم 2", "fields": {"f0": "طلب حذف حساب زميل"}, "hidden": []}, {"id": "base-3", "kind": "existing", "label": "قسم 3", "fields": {"f0": "يمكنك طلب حذف حسابك وبياناته دون إعادة تثبيت التطبيق. إرسال الطلب لا يعني أن الحذف اكتمل؛ نتحقق من ملكية الحساب ثم نعالج الطلب."}, "hidden": []}, {"id": "base-4", "kind": "existing", "label": "قسم 4", "fields": {"f0": "من داخل التطبيق"}, "hidden": []}, {"id": "base-5", "kind": "existing", "label": "قسم 5", "fields": {"f0": "افتح إعدادات الحساب.", "f1": "اختر «حذف الحساب» واقرأ رسالة التأكيد.", "f2": "أكد الطلب. قد تحتاج بعض الحسابات إلى مراجعة أو نقل ملكية محتوى مشترك."}, "hidden": []}, {"id": "base-6", "kind": "existing", "label": "قسم 6", "fields": {"f0": "من خارج التطبيق"}, "hidden": []}, {"id": "base-7", "kind": "existing", "label": "قسم 7", "fields": {"f0": "أرسل الطلب من البريد المسجّل في زميل إلى ", "f1": "mailto:zameel.jo@gmail.com", "f2": "zameel.jo@gmail.com", "f3": "https://mail.google.com/mail/?view=cm&fs=1&to=zameel.jo%40gmail.com", "f4": "فتح Gmail", "f5": "نسخ البريد", "f6": ". إذا فقدت الوصول إليه، ", "f7": "https://wa.me/962792009821", "f8": "تواصل عبر واتساب", "f9": " لاستكمال التحقق من الملكية."}, "hidden": []}, {"id": "base-8", "kind": "existing", "label": "قسم 8", "fields": {"f0": "البريد المسجّل في زميل", "f1": "ملاحظات اختيارية", "f2": "تجهيز رسالة طلب الحذف"}, "hidden": []}, {"id": "base-9", "kind": "existing", "label": "قسم 9", "fields": {"f0": "هذا النموذج يفتح برنامج البريد فقط. راجع الرسالة واضغط «إرسال» من بريد حسابك. لا تُحفظ المعلومات في هذا الموقع، ولا يُحذف الحساب تلقائيًا. إن لم يفتح البريد، استخدم العنوان أعلاه وأرسل بعنوان «طلب حذف حساب زميل»."}, "hidden": []}, {"id": "base-10", "kind": "existing", "label": "قسم 10", "fields": {"f0": "ما الذي يشمله الحذف؟"}, "hidden": []}, {"id": "base-11", "kind": "existing", "label": "قسم 11", "fields": {"f0": "بيانات الدخول والملف الشخصي والمحتوى والملفات المرتبطة بالحساب التي تغطيها آلية التنظيف. تعالج العملية في الخلفية وقد تتأخر عند تعثر إحدى مراحلها. المحتوى المشترك وملكية المجموعات والحسابات الإدارية أو التجارية قد تحتاج مراجعة قبل الإكمال."}, "hidden": []}, {"id": "base-12", "kind": "existing", "label": "قسم 12", "fields": {"f0": "لا يمكن حذف نسخ حفظها الآخرون خارج زميل. تنظف معرّفات مهام الحذف المكتملة دوريًا بعد سبعة أيام؛ وقد تبقى نسخ احتياطية أو سجلات تشغيلية حتى انتهاء مدة الاحتفاظ المطبقة لدى مزود الخدمة. اقرأ ", "f1": "/privacy/", "f2": "سياسة الخصوصية", "f3": " أو تواصل للاستفسار عن بيانات محددة."}, "hidden": []}, {"id": "base-14", "kind": "existing", "label": "أسفل الصفحة", "fields": {"f0": "© 2026 Zameel — زميل · ", "f1": "mailto:zameel.jo@gmail.com", "f2": "تواصل مع إدارة زميل", "f3": "https://mail.google.com/mail/?view=cm&fs=1&to=zameel.jo%40gmail.com", "f4": "فتح Gmail", "f5": "نسخ البريد", "f6": " · ", "f7": "/privacy/", "f8": "سياسة الخصوصية", "f9": " · ", "f10": "/child-safety/", "f11": "حماية الأطفال"}, "hidden": []}]}, {"id": "/child-safety/", "title": "سلامة الأطفال", "blocks": [{"id": "base-0", "kind": "existing", "label": "الشريط العلوي", "fields": {"f0": "/", "f1": "/assets/zameel-logo.png", "f2": "شعار زميل", "f3": "ZAMEEL ", "f4": "زميل", "f5": "/privacy/", "f6": "الخصوصية", "f7": "/support/", "f8": "الدعم", "f9": "/delete-account/", "f10": "حذف الحساب"}, "hidden": []}, {"id": "base-1", "kind": "existing", "label": "قسم 1", "fields": {"f0": "مجتمع زميل الآمن"}, "hidden": []}, {"id": "base-2", "kind": "existing", "label": "قسم 2", "fields": {"f0": "معايير حماية الأطفال"}, "hidden": []}, {"id": "base-3", "kind": "existing", "label": "قسم 3", "fields": {"f0": "تاريخ السريان: 7 أكتوبر 2026"}, "hidden": []}, {"id": "base-4", "kind": "existing", "label": "قسم 4", "fields": {"f0": "يحظر تطبيق Zameel — زميل الاستغلال والاعتداء الجنسي على الأطفال، وأي محتوى أو سلوك يعرّض سلامتهم للخطر. تنطبق هذه المعايير على المنشورات والحالات والشورتس والملفات الشخصية والدردشة والمكالمات والراديو والألعاب وجميع خدمات زميل. ويُقصد بالطفل في هذه المعايير كل شخص دون 18 عامًا."}, "hidden": []}, {"id": "base-5", "kind": "existing", "label": "قسم 5", "fields": {"f0": "ما الذي نحظره؟"}, "hidden": []}, {"id": "base-6", "kind": "existing", "label": "قسم 6", "fields": {"f0": "إنشاء أو رفع أو نشر أو طلب أو تداول مواد الاعتداء الجنسي على الأطفال، بما فيها الصور والفيديوهات والمواد المصطنعة أو المعدلة التي تصوّر استغلالًا جنسيًا للأطفال.", "f1": "استدراج الأطفال لأغراض جنسية، والابتزاز الجنسي، والاتجار بالأطفال أو تسهيل استغلالهم.", "f2": "التواصل الجنسي مع الأطفال أو طلب صور أو معلومات أو لقاءات بغرض استغلالهم.", "f3": "نشر روابط أو تعليمات أو حسابات تسهّل الوصول إلى هذا المحتوى، أو تشجيع الاعتداء أو تبريره."}, "hidden": []}, {"id": "base-7", "kind": "existing", "label": "قسم 7", "fields": {"f0": "كيف تقدم بلاغًا؟"}, "hidden": []}, {"id": "base-8", "kind": "existing", "label": "قسم 8", "fields": {"f0": "استخدم خيار الإبلاغ المتاح داخل التطبيق على المحتوى أو الحساب، أو تواصل مع جهة حماية الأطفال في زميل عبر البريد أدناه. أرسل نوع المشكلة واسم الحساب أو رابط المحتوى أو معرّفه، والوقت التقريبي للحادثة إن أمكن."}, "hidden": []}, {"id": "base-9", "kind": "existing", "label": "قسم 9", "fields": {"f0": "لا تنزّل أو تعيد إرسال مواد الاعتداء الجنسي على الأطفال، ولا ترفقها برسالتك.", "f1": " يكفي وصف الواقعة وتحديد مكانها لتتم مراجعتها. لا ترسل كلمة مرور أو رمز تحقق."}, "hidden": []}, {"id": "base-10", "kind": "existing", "label": "قسم 10", "fields": {"f0": "mailto:zameel.jo@gmail.com?subject=Zameel%20Child%20Safety%20Report", "f1": "إرسال بلاغ لحماية الأطفال"}, "hidden": []}, {"id": "base-11", "kind": "existing", "label": "قسم 11", "fields": {"f0": "https://mail.google.com/mail/?view=cm&fs=1&to=zameel.jo%40gmail.com&su=Zameel%20Child%20Safety%20Report", "f1": "فتح Gmail", "f2": "نسخ البريد"}, "hidden": []}, {"id": "base-12", "kind": "existing", "label": "قسم 12", "fields": {"f0": "zameel.jo@gmail.com"}, "hidden": []}, {"id": "base-13", "kind": "existing", "label": "قسم 13", "fields": {"f0": "التعامل مع البلاغات والمخالفات"}, "hidden": []}, {"id": "base-14", "kind": "existing", "label": "قسم 14", "fields": {"f0": "تلتزم إدارة زميل بمراجعة بلاغات حماية الأطفال واتخاذ الإجراءات المناسبة عند العلم بمحتوى مخالف، بما يشمل إزالة المحتوى أو تقييد الوصول إليه، وتعليق الحسابات المخالفة أو إيقافها وفق طبيعة المخالفة والقانون المعمول به."}, "hidden": []}, {"id": "base-15", "kind": "existing", "label": "قسم 15", "fields": {"f0": "تتعامل الإدارة مع المعلومات المرتبطة بالبلاغ بسرية وبقدر الحاجة للتحقيق والحماية، وتحفظ الأدلة اللازمة بطريقة قانونية، وتُبلغ الجهات المختصة عن مواد الاعتداء الجنسي على الأطفال المؤكدة وفق القوانين والمتطلبات الواجبة التطبيق. وقد تتعاون مع الجهات المختصة لمنع الضرر والتحقيق فيه."}, "hidden": []}, {"id": "base-16", "kind": "existing", "label": "قسم 16", "fields": {"f0": "جهة الاتصال بحماية الأطفال"}, "hidden": []}, {"id": "base-17", "kind": "existing", "label": "قسم 17", "fields": {"f0": "إدارة زميل مسؤولة عن استقبال بلاغات حماية الأطفال والإشعارات المرتبطة بها، والتنسيق بشأن مراجعتها وإجراءات التعامل معها. بريد الاتصال الرسمي هو ", "f1": "mailto:zameel.jo@gmail.com", "f2": "zameel.jo@gmail.com", "f3": "https://mail.google.com/mail/?view=cm&fs=1&to=zameel.jo%40gmail.com", "f4": "فتح Gmail", "f5": "نسخ البريد", "f6": "."}, "hidden": []}, {"id": "base-18", "kind": "existing", "label": "قسم 18", "fields": {"f0": "عند وجود خطر فوري"}, "hidden": []}, {"id": "base-19", "kind": "existing", "label": "قسم 19", "fields": {"f0": "إذا كان طفل في خطر مباشر، تواصل فورًا مع خدمات الطوارئ أو جهات حماية الطفل المختصة في بلدك. بلاغ زميل لا يحل محل طلب المساعدة العاجلة."}, "hidden": []}, {"id": "base-20", "kind": "existing", "label": "قسم 20", "fields": {"f0": "نطاق الاستخدام والتحديثات"}, "hidden": []}, {"id": "base-21", "kind": "existing", "label": "قسم 21", "fields": {"f0": "زميل موجّه للأشخاص من عمر 16 سنة فأكثر. لا يُعفي ذلك أي مستخدم من الالتزام بهذه المعايير، وتبقى حماية المستخدمين دون 18 عامًا أولوية. قد تُحدّث هذه المعايير، ويُعرض تاريخ تحديثها في هذه الصفحة."}, "hidden": []}, {"id": "base-22", "kind": "existing", "label": "قسم 22", "fields": {"f0": "للمزيد: ", "f1": "/privacy/", "f2": "سياسة الخصوصية", "f3": " · ", "f4": "/support/", "f5": "الدعم", "f6": " · ", "f7": "/delete-account/", "f8": "طلب حذف الحساب"}, "hidden": []}, {"id": "base-23", "kind": "existing", "label": "أسفل الصفحة", "fields": {"f0": "© 2026 Zameel — زميل · ", "f1": "mailto:zameel.jo@gmail.com", "f2": "تواصل مع إدارة زميل", "f3": "https://mail.google.com/mail/?view=cm&fs=1&to=zameel.jo%40gmail.com", "f4": "فتح Gmail", "f5": "نسخ البريد", "f6": " · ", "f7": "/privacy/", "f8": "سياسة الخصوصية", "f9": " · ", "f10": "/child-safety/", "f11": "حماية الأطفال"}, "hidden": []}]}]}$seed$::jsonb,$seed${"schema": 1, "pages": [{"id": "/", "title": "الرئيسية", "blocks": [{"id": "base-0", "kind": "existing", "label": "الشريط العلوي", "fields": {"f0": "/", "f1": "/assets/zameel-logo.png", "f2": "شعار زميل", "f3": "ZAMEEL ", "f4": "زميل", "f5": "#about", "f6": "عن زميل", "f7": "#app-tour", "f8": "داخل التطبيق", "f9": "/privacy/", "f10": "الخصوصية", "f11": "/support/", "f12": "الدعم", "f13": "/delete-account/", "f14": "حذف الحساب"}, "hidden": []}, {"id": "base-1", "kind": "existing", "label": "زميل. مجتمعك أقرب.", "fields": {"f0": " من الأردن، إلى كل من يبحث عن زميل", "f1": "زميل.", "f2": "مجتمعك أقرب.", "f3": "منصة أردنية تجمع التواصل والمعرفة والفرص في تجربة واحدة، مفتوحة للجميع، وبخدمات تنتمي إلى الحياة الجامعية.", "f4": "شارك المنشورات والحالات والشورتس، وابنِ زمالات جديدة عبر الدردشة والمكالمات الصوتية والمرئية. اكتشف المكتبة وتبادل الكتب، واجتمع للدراسة أو تقديم المحاضرات، واستفد من زميل AI وفرص العمل والتدريب وخدمات المجتمع.", "f5": "#app-tour", "f6": "شاهد زميل من الداخل ↓", "f7": "/support/", "f8": "تواصل معنا", "f9": "قريبًا على المتاجر · ستُضاف روابط التنزيل الرسمية عند الإطلاق", "f10": "/assets/campus.webp", "f11": "مشهد توضيحي لزملاء في حرم جامعي أردني", "f12": "لحظات تجمعنا ", "f13": "/assets/zameel-logo.png", "f14": "", "f15": " زميلك أقرب مما تتخيّل"}, "hidden": []}, {"id": "base-2", "kind": "existing", "label": "كل ما تحتاجه لتتواصل، تتعلّم، وتكتشف.", "fields": {"f0": "تجربة واحدة، وأبواب كثيرة", "f1": "كل ما تحتاجه لتتواصل،", "f2": "تتعلّم، وتكتشف.", "f3": "01", "f4": "التواصل والمحتوى", "f5": "منشورات نصية وصور وفيديوهات، حالات وشورتس، وإعجابات وتعليقات ومشاركات، مع خيارات لتحديد جمهور المحتوى، وتنزيل الصور والشورتس المتاحة للحفظ بعلامة زميل.", "f6": "02", "f7": "الدردشة والمكالمات", "f8": "رسائل وصور وفيديوهات ومقاطع صوتية، مكالمات صوتية ومرئية، وإشعارات تساعدك على متابعة الرسائل والتفاعل.", "f9": "03", "f10": "المكتبة وتبادل الكتب", "f11": "ملفات ومراجع دراسية، وبيع الكتب وتبادلها وإعارتها والتبرع بها، مع الحجز والتواصل مع صاحب الكتاب ومتابعة الطلب.", "f12": "04", "f13": "اجتمع بزميل", "f14": "مساحة للاجتماعات متعددة المشاركين، والتعاون في الدراسة وتقديم المحاضرات والجلسات التعليمية بالصوت والفيديو.", "f15": "05", "f16": "زميل AI", "f17": "مساعد داخل التطبيق يساندك في الأسئلة وشرح الأفكار والتعلم وتنظيم المعرفة.", "f18": "06", "f19": "الوظائف وفرص التدريب", "f20": "مسار لاكتشاف الوظائف والفرص التدريبية، يساعد الطلبة وغيرهم على الانتقال من المعرفة إلى التجربة العملية.", "f21": "07", "f22": "المجتمع الجامعي", "f23": "مساحات للجامعة والكلية والتخصص والدفعة، وتقويم أكاديمي، وخدمات للمجتمع الجامعي وشركاء زميل.", "f24": "08", "f25": "العالم القريب منك", "f26": "اكتشاف الحرم الجامعي والمحيط القريب، مع زمالات مقترحة تساعد على بناء مجتمع أكثر ترابطًا.", "f27": "09", "f28": "الراديو والاستطلاعات", "f29": "راديو زميل للمشاركة الصوتية، واستطلاعات للرأي، وتحدي أجمل كلية للاحتفاء بصور الحياة الجامعية.", "f30": "10", "f31": "التعلم والألعاب", "f32": "كويز للأسئلة والمعرفة، وثقة أم غدر للتعاون واتخاذ القرار، بعملات افتراضية داخل تجربة اللعب.", "f33": "11", "f34": "حسابك ومظهرك", "f35": "تسجيل بالبريد الإلكتروني مع تأكيده، وملف شخصي وإعدادات مستقلة للحساب والتطبيق، ومظهر فاتح وداكن وأصلي، وخدمة توثيق مدفوعة بعد مراجعة الإدارة.", "f36": "12", "f37": "الترويج والخصوصية", "f38": "ترويج المنشورات العامة باختيار المدة والجمهور والمناطق أو الجامعات والعمر والجنس، إلى جانب التحكم بالخصوصية والإبلاغ والحذف والدعم."}, "hidden": []}, {"id": "base-3", "kind": "existing", "label": "تعرف على تجربتك القادمة.", "fiel